-- ==============================================================================================
-- BASELINE — the tables this repository's migration history never created.
--
-- Generated by scripts/gen_baseline_migration.mjs from production's catalog. Do not hand-edit:
-- re-run the generator instead, so the file cannot drift from the database it describes.
--
-- 13 table(s) are ALTERed, INSERTed into and INDEXed by later migrations and created by
-- none of them. They exist on production and staging because they were made directly in the
-- database, so the written history could describe this platform but never rebuild it. That is
-- why the Supabase Preview check — which replays onto an EMPTY database — had never passed.
--
-- Every statement is idempotent. On production and staging this file is a no-op in full; on an
-- empty database it is the foundation everything after it assumes.
--
-- Foreign keys come after every table, never inline, because an inline reference to a table
-- created later is the exact defect this baseline exists to end.
-- ==============================================================================================

-- Extensions the column types depend on.
create extension if not exists vector;

-- Sequences backing serial-style defaults. Identity columns are not here: they make their own.
create sequence if not exists public.agent_actions_id_seq;
create sequence if not exists public.agent_command_log_id_seq;
create sequence if not exists public.agent_runs_id_seq;
create sequence if not exists public.expense_entries_id_seq;
create sequence if not exists public.expenses_id_seq;

-- ── public.agent_actions ─────────────────────────────────────────────────────────────────
create table if not exists public.agent_actions (
  id bigint default nextval('agent_actions_id_seq'::regclass),
  agent text,
  kind text,
  status text default 'pending'::text,
  risk text default 'low'::text,
  title text,
  recommendation text,
  detail jsonb default '{}'::jsonb,
  target_table text,
  target_id text,
  created_at timestamp with time zone default now(),
  decided_at timestamp with time zone,
  decided_by text,
  confidence numeric,
  evidence jsonb,
  escalated boolean default false,
  escalation_reason text,
  decision_log_id bigint,
  constraint agent_actions_pkey PRIMARY KEY (id)
);
alter table public.agent_actions enable row level security;
create unique index if not exists agent_actions_dedupe ON public.agent_actions USING btree (agent, kind, target_id) WHERE (status = 'pending'::text);
create index if not exists agent_actions_status_idx ON public.agent_actions USING btree (status, created_at DESC);

-- ── public.agent_command_log ─────────────────────────────────────────────────────────────
create table if not exists public.agent_command_log (
  id bigint default nextval('agent_command_log_id_seq'::regclass),
