-- ── public.company_faq ───────────────────────────────────────────────────────────────────
create table if not exists public.company_faq (
  id bigint generated always as identity,
  section text default 'General'::text,
  sort integer default 0,
  question text,
  answer text,
  audience text default 'all'::text,
  status text default 'draft'::text,
  source_note text,
  tags text[] default '{}'::text[],
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now(),
  approved_at timestamp with time zone,
  approved_by text,
  public boolean default false,
  embedding_gte vector(384),
  constraint company_faq_pkey PRIMARY KEY (id)
);
alter table public.company_faq enable row level security;
create index if not exists company_faq_emb_idx ON public.company_faq USING ivfflat (embedding_gte vector_cosine_ops) WITH (lists='20');
create unique index if not exists uq_company_faq_q ON public.company_faq USING btree (question);

-- ── public.crm_activities ────────────────────────────────────────────────────────────────
create table if not exists public.crm_activities (
  id uuid default gen_random_uuid(),
  entity text,
  entity_id text,
  type text,
  subject text,
  body text,
  actor text,
  due_at timestamp with time zone,
  done boolean default false,
  done_at timestamp with time zone,
  meta jsonb,
  created_at timestamp with time zone default now(),
  constraint crm_activities_pkey PRIMARY KEY (id)
);
alter table public.crm_activities enable row level security;
create index if not exists idx_crm_activities_entity ON public.crm_activities USING btree (entity, entity_id, created_at DESC);
create index if not exists idx_crm_activities_tasks ON public.crm_activities USING btree (type, done, due_at) WHERE (type = 'task'::text);

